<?php
require_once __DIR__.'/backend/authorization.php';require_once __DIR__.'/backend/db.php';require_once __DIR__.'/backend/csrf.php';requireRegularAdmin();
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$id=(int)($_POST['user_id']??0);$phone=normalizePhilippinePhone((string)($_POST['phone_number']??''));$prefs=trim((string)($_POST['nail_preferences']??''));$allergies=trim((string)($_POST['allergy_notes']??''));$tech=($_POST['preferred_technician_id']??'')!==''?(int)$_POST['preferred_technician_id']:null;if($id>0&&$phone){$u=$conn->prepare("UPDATE users SET phone_number=?,preferred_technician_id=?,nail_preferences=?,allergy_notes=? WHERE id=? AND role='user'");$u->bind_param('sissi',$phone,$tech,$prefs,$allergies,$id);$u->execute();audit($conn,'customer_profile_updated','user',$id);redirectTo('customers.php?saved=1');}}
$q=trim((string)($_GET['q']??''));if($q!==''){$like='%'.$q.'%';$s=$conn->prepare("SELECT u.*,t.full_name technician_name FROM users u LEFT JOIN technicians t ON t.id=u.preferred_technician_id WHERE u.role='user' AND (u.full_name LIKE ? OR u.email LIKE ? OR u.phone_number LIKE ?) ORDER BY u.full_name");$s->bind_param('sss',$like,$like,$like);$s->execute();$customers=$s->get_result();}else{$customers=$conn->query("SELECT u.*,t.full_name technician_name FROM users u LEFT JOIN technicians t ON t.id=u.preferred_technician_id WHERE u.role='user' ORDER BY u.full_name");}$techs=$conn->query("SELECT id,full_name FROM technicians WHERE status='active' ORDER BY full_name")->fetch_all(MYSQLI_ASSOC);
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customers | Oh My Gracious</title><link rel="stylesheet" href="css/style.css"></head><body><header class="navbar"><div class="logo">Front Desk</div><nav><a href="admin-dashboard.php">Dashboard</a><a href="admin-bookings.php">Appointments</a><a class="active" href="customers.php">Customers</a><a href="staff-security.php">Security</a><a href="logout.php" class="logout-btn">Logout</a></nav></header><main class="page-wrap"><div class="page-heading"><div><p class="eyebrow">CUSTOMER ACCOUNTS</p><h1>Customer List</h1><p>Authorized salon staff can update service-related preferences and contact information.</p></div></div><?php if(isset($_GET['saved'])):?><div class="alert success">Customer information updated.</div><?php endif;?><form class="filter-bar"><input name="q" placeholder="Search name, email, or phone" value="<?=h($q)?>"><button class="btn secondary small">Search</button></form><div class="customer-grid"><?php while($c=$customers->fetch_assoc()):?><article class="panel"><div class="section-heading"><div><h3><?=h($c['full_name'])?></h3><p><?=h($c['email'])?></p></div><span class="status <?=h($c['account_status'])?>"><?=h($c['account_status'])?></span></div><form method="POST" class="form-grid two"><?=csrfInput()?><input type="hidden" name="user_id" value="<?= (int)$c['id']?>"><div class="field"><label>Phone</label><input name="phone_number" value="<?=h($c['phone_number'])?>"></div><div class="field"><label>Preferred Technician</label><select name="preferred_technician_id"><option value="">No preference</option><?php foreach($techs as $t):?><option value="<?= (int)$t['id']?>" <?= (int)$c['preferred_technician_id']===(int)$t['id']?'selected':''?>><?=h($t['full_name'])?></option><?php endforeach;?></select></div><div class="field span-2"><label>Nail Preferences</label><textarea name="nail_preferences" rows="2"><?=h($c['nail_preferences'])?></textarea></div><div class="field span-2"><label>Allergies / Sensitivities</label><textarea name="allergy_notes" rows="2"><?=h($c['allergy_notes'])?></textarea></div><div class="span-2"><button class="btn secondary small">Save Customer Notes</button></div></form></article><?php endwhile;?></div></main></body></html>
